<details class="card"><summary>Перевірити або уточнити адресу старого замовлення</summary><form method="post"><?php npFormFields($orderId); ?><label>Тип доставки<select name="delivery_type"><option value="branch">Відділення</option><option value="postomat">Поштомат</option><option value="courier">Кур’єр</option></select></label><label>City Ref<input name="city_ref" required></label><label>Warehouse Ref<input name="warehouse_ref"></label><label>Street Ref (кур’єр)<input name="street_ref"></label><div class="two"><label>Будинок<input name="building"></label><label>Квартира<input name="flat"></label></div><button name="action" value="verify_address">Перевірити адресу в НП</button></form></details>
