<?php foreach($group as $l): $i=(int)$l['line_no'];$item=$order['items'][$i]??[]; ?><div class="line"><div><strong><?=esc($item['name']??$l['sku'])?></strong><small><?=esc($item['variant']??'')?> · <?=esc($l['sku'])?> · залишилось <?=$left[$i]['qty']?> <?=($l['sale_unit']??'')==='m2'?'м²':'шт.'?></small></div><label>У посилку<input type="number" name="line_qty[<?=$i?>]" step="<?=($l['sale_unit']??'')==='m2'?'0.01':'1'?>" min="0" max="<?=$left[$i]['qty']?>" value="<?=$left[$i]['qty']?>" <?=$code===''?'disabled':''?>></label></div><?php endforeach; ?>
<?php if($code!==''): ?><label>Фактичні місця: вага (кг), довжина/ширина/висота (см)<textarea name="places" rows="4" required placeholder='[{"weight":ФАКТИЧНА_ВАГА,"length":ДОВЖИНА,"width":ШИРИНА,"height":ВИСОТА}]'></textarea></label><p class="muted">Кожен об’єкт — одне фізичне місце. Вага не підставляється автоматично. Можна розділити товари на кілька чернеток одного постачальника.</p><button name="action" value="draft">Зберегти чернетку посилки</button><?php endif; ?></form></div><?php endforeach; ?>
<div class="card"><h2>Артикули постачальників</h2><p>Заповніть перед автоматичним повідомленням. Після створення ТТН постачальнику передаються тільки його позиції та номер ТТН.</p><form method="post"><?php npFormFields($orderId);$native=supplierSkuRows($db,$orderId);foreach($lines as $ln):?><label><?=esc($order['items'][(int)$ln['line_no']]['name']??$ln['sku'])?> · <?=esc($ln['sku'])?><input name="supplier_sku[<?=(int)$ln['line_no']?>]" maxlength="120" value="<?=esc((string)($native[(int)$ln['line_no']]??(cfg('supplier_sku_map')??[])[$ln['sku']]??''))?>" placeholder="Артикул із файлу постачальника"></label><?php endforeach;?><button name="action" value="supplier_skus">Зберегти артикули</button></form></div><h2>3. Посилки та ТТН</h2><?php foreach($ships as $s): ?><div class="card"><h3>Посилка <?=(int)$s['id']?> · <?=esc($s['supplier_code'])?></h3><p><?=esc(npStatusLabel($s['status']))?><?php if($s['tracking_number']): ?> · <strong><?=esc($s['tracking_number'])?></strong><?php endif; ?></p><p><?=esc($s['origin_label'])?></p><p>Оголошена вартість: <?=esc(customerMoney($s['declared_value']??0))?></p><pre><?=esc(json_encode(json_decode((string)$s['package_json'],true),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))?></pre><?php if($s['error']): ?><p class="error"><?=esc($s['error'])?></p><?php endif; ?><form method="post" class="actions"><?php npFormFields($orderId,(int)$s['id']); ?><?php if($s['status']==='draft'): ?><button name="action" value="create">Перевірити та створити ТТН</button><?php endif; ?><?php if(in_array($s['status'],['unknown','creating'],true)): ?><button name="action" value="reconcile">Звірити результат у НП</button><?php endif; ?><?php if(in_array($s['status'],['draft','error'],true)): ?><button class="secondary" name="action" value="cancel_draft">Скасувати чернетку</button><?php endif; ?><?php if($s['tracking_number']): ?><button class="secondary" name="action" value="supplier_ack">Постачальник підтвердив «передано»</button><a class="button secondary" href="/shop/np-print.php?shipment=<?=(int)$s['id']?>" target="_blank" rel="noopener">Дані ТТН для друку →</a><?php endif; ?></form><?php if(shopStaffRole($actor)==='OWNER'&&in_array($s['status'],['unknown','creating'],true)): ?><details><summary>Розібрати ТТН з невідомим результатом</summary><p>Потрібен вхід власника протягом останніх 15 хвилин і причина рішення. «Не створена» доступна після повної звірки з 0 збігів понад 2 години тому.</p><form method="post"><?php npFormFields($orderId,(int)$s['id']); ?><label>Результат<select name="resolution" required><option value="link">Прив’язати існуючу ТТН</option><?php if(!empty($s['reconciliation_zero_at'])&&(int)($s['reconciliation_matches']??-1)===0&&strtotime($s['reconciliation_zero_at'].' UTC')<time()-7200): ?><option value="not_created">У НП не створена</option><?php endif; ?></select></label><label>Існуюча ТТН (14 цифр)<input name="tracking_number" pattern="[0-9]{14}" maxlength="14"></label><label>Причина рішення<input name="resolution_reason" minlength="6" maxlength="400" required></label><button name="action" value="resolve_unknown">Розібрати ТТН з невідомим результатом</button></form></details><?php endif; ?></div><?php endforeach; ?>
<?php endif; ?></section></div><p class="muted">Офіційні бланки й скасування вже створених ТТН доступні у <a href="https://new.novaposhta.ua/" target="_blank" rel="noopener noreferrer">бізнес-кабінеті НП</a>. Повернення та скасування не змінюють статус оплати.</p></main></body></html>
